// A stale lazily-loaded chunk (Vite re-optimising deps in dev, or a new deploy
// swapping hashed asset URLs) makes route/preload imports reject. Reload once to
// pull a fresh module graph instead of leaving the page stuck.
window.addEventListener('vite:preloadError', () => {
	if (sessionStorage.getItem('nao:chunk-error-reloaded') === '1') return;
	sessionStorage.setItem('nao:chunk-error-reloaded', '1');
	window.location.reload();
});

window.addEventListener('vite:preloadError', () => {
	if (sessionStorage.getItem('nao:chunk-error-reloaded') === '1') return;
	sessionStorage.setItem('nao:chunk-error-reloaded', '1');
	window.location.reload();
});

// Once the app has stayed healthy for a bit, drop the guard so a genuinely new
// stale-chunk event can self-heal again without risking a reload loop.
setTimeout(() => sessionStorage.removeItem('nao:chunk-error-reloaded'), 5000);

